CREATE TABLE IF NOT EXISTS enforcement_cases_v2(id TEXT PRIMARY KEY,subject_user_id TEXT NOT NULL REFERENCES users(id),document_id TEXT REFERENCES documents(id),residency_number TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),reason TEXT NOT NULL,ministry_id INTEGER NOT NULL CHECK(ministry_id IN (1,3,7)),created_by TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),decided_by TEXT REFERENCES users(id),decided_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,action TEXT NOT NULL DEFAULT 'debt' CHECK(action IN ('debt','service_suspension','both')),CHECK(action='service_suspension' OR amount>0));
INSERT OR IGNORE INTO enforcement_cases_v2(id,subject_user_id,document_id,residency_number,amount,reason,ministry_id,created_by,status,decided_by,decided_at,created_at,action) SELECT id,subject_user_id,document_id,residency_number,amount,reason,ministry_id,created_by,status,decided_by,decided_at,created_at,action FROM enforcement_cases;
CREATE INDEX IF NOT EXISTS idx_enforcement_v2_subject ON enforcement_cases_v2(subject_user_id,status);
CREATE TABLE IF NOT EXISTS service_suspensions_v2(id TEXT PRIMARY KEY,case_id TEXT NOT NULL UNIQUE REFERENCES enforcement_cases_v2(id),subject_user_id TEXT NOT NULL REFERENCES users(id),ministry_id INTEGER NOT NULL CHECK(ministry_id IN (1,3,7)),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','lifted')),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at TEXT,ended_by TEXT REFERENCES users(id),lift_reason TEXT);
INSERT OR IGNORE INTO service_suspensions_v2(id,case_id,subject_user_id,ministry_id,reason,status,created_by,created_at,ended_at,ended_by,lift_reason) SELECT s.id,s.case_id,s.subject_user_id,c.ministry_id,s.reason,s.status,s.created_by,s.created_at,s.ended_at,s.ended_by,s.lift_reason FROM service_suspensions s JOIN enforcement_cases_v2 c ON c.id=s.case_id;
CREATE INDEX IF NOT EXISTS idx_suspensions_v2_user ON service_suspensions_v2(subject_user_id,status);